def chains_for(x0, x1, nw=9, cov=7):
    centers = [int(x0 + 150 + (x1 - x0 - 300) * i / (nw - 1)) for i in range(nw)]
    wins = [groups_in(c - 60, c + 60) for c in centers]
    mid = nw // 2
    chains = []
    for y in wins[mid]:
        ch = {mid: y}
        # extend right
        for w in range(mid + 1, nw):
            prev = ch[max(k for k in ch if k < w)]
            cand = [v for v in wins[w] if abs(v - prev) <= 12]
            if cand:
                ch[w] = min(cand, key=lambda v: abs(v - prev))
        # extend left
        for w in range(mid - 1, -1, -1):
            prev = ch[min(k for k in ch if k > w)]
            cand = [v for v in wins[w] if abs(v - prev) <= 12]
            if cand:
                ch[w] = min(cand, key=lambda v: abs(v - prev))
        if len(ch) >= cov:
            chains.append((ch, centers))

